window.ScripturaLexicons.BDAG_PART_0169 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0169-01\" data-source=\"BDAG\" data-search=\"θήρ, ός, ὁ substantivo masculino animal; fera; animal selvagem BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θήρ, ός, ὁ</td><td>substantivo masculino</td><td>animal; fera; animal selvagem</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0169-02\" data-source=\"BDAG\" data-search=\"θήρα, ας, ἡ substantivo feminino rede; armadilha; laço BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θήρα, ας, ἡ</td><td>substantivo feminino</td><td>rede; armadilha; laço</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0169-03\" data-source=\"BDAG\" data-search=\"θηρεύω verbo caçar; capturar; apanhar em palavras; enganar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θηρεύω</td><td>verbo</td><td>caçar; capturar; apanhar em palavras; enganar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0169-04\" data-source=\"BDAG\" data-search=\"θηριομαχέω verbo combater animais selvagens; lutar com adversários BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θηριομαχέω</td><td>verbo</td><td>combater animais selvagens; lutar com adversários</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0169-05\" data-source=\"BDAG\" data-search=\"θηριομαχίον, ου, τό substantivo neutro combate com feras BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θηριομαχίον, ου, τό</td><td>substantivo neutro</td><td>combate com feras</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0169-06\" data-source=\"BDAG\" data-search=\"θηριομάχος, ον adjetivo de dois gêneros que combate feras; combatente de feras BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θηριομάχος, ον</td><td>adjetivo de dois gêneros</td><td>que combate feras; combatente de feras</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0169-07\" data-source=\"BDAG\" data-search=\"θηρίον, ου, τό substantivo neutro animal; fera; animal monstruoso; pessoa feroz BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θηρίον, ου, τό</td><td>substantivo neutro</td><td>animal; fera; animal monstruoso; pessoa feroz</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0169-08\" data-source=\"BDAG\" data-search=\"θησαυρίζω verbo guardar; acumular; entesourar; reservar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θησαυρίζω</td><td>verbo</td><td>guardar; acumular; entesourar; reservar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0169-09\" data-source=\"BDAG\" data-search=\"θησαυρός, οῦ, ὁ substantivo masculino depósito; arca; tesouro; bens guardados BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θησαυρός, οῦ, ὁ</td><td>substantivo masculino</td><td>depósito; arca; tesouro; bens guardados</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0169-10\" data-source=\"BDAG\" data-search=\"θιγγάνω verbo tocar; pôr a mão em; atingir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θιγγάνω</td><td>verbo</td><td>tocar; pôr a mão em; atingir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0169-11\" data-source=\"BDAG\" data-search=\"θλάω verbo quebrar; romper; partir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θλάω</td><td>verbo</td><td>quebrar; romper; partir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0169-12\" data-source=\"BDAG\" data-search=\"θλίβω verbo comprimir; estreitar; oprimir; afligir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θλίβω</td><td>verbo</td><td>comprimir; estreitar; oprimir; afligir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0169-13\" data-source=\"BDAG\" data-search=\"θλῖψις, εως, ἡ substantivo feminino pressão; opressão; tribulação; aflição BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θλῖψις, εως, ἡ</td><td>substantivo feminino</td><td>pressão; opressão; tribulação; aflição</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0169-14\" data-source=\"BDAG\" data-search=\"θνῄσκω verbo morrer; estar morto; morrer espiritualmente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θνῄσκω</td><td>verbo</td><td>morrer; estar morto; morrer espiritualmente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0169-15\" data-source=\"BDAG\" data-search=\"θνητός, ή, όν adjetivo mortal; sujeito à morte BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θνητός, ή, όν</td><td>adjetivo</td><td>mortal; sujeito à morte</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0169-16\" data-source=\"BDAG\" data-search=\"θορυβάζω verbo perturbar; estar preocupado; distrair-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θορυβάζω</td><td>verbo</td><td>perturbar; estar preocupado; distrair-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0169-17\" data-source=\"BDAG\" data-search=\"θορυβέω verbo causar tumulto; agitar; perturbar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θορυβέω</td><td>verbo</td><td>causar tumulto; agitar; perturbar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0169-18\" data-source=\"BDAG\" data-search=\"θόρυβος, ου, ὁ substantivo masculino clamor; confusão; tumulto; agitação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θόρυβος, ου, ὁ</td><td>substantivo masculino</td><td>clamor; confusão; tumulto; agitação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0169-19\" data-source=\"BDAG\" data-search=\"θράσος, ους, τό substantivo neutro coragem; temeridade; arrogância; insolência BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θράσος, ους, τό</td><td>substantivo neutro</td><td>coragem; temeridade; arrogância; insolência</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0169-20\" data-source=\"BDAG\" data-search=\"θρασύτης, ητος, ἡ substantivo feminino ousadia; insolência; arrogância BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θρασύτης, ητος, ἡ</td><td>substantivo feminino</td><td>ousadia; insolência; arrogância</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0169-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θήρ, ός, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Homero e outros; Sb 4011, 4; LXX; ViDa 7 [p. 77, 13 Sch.]; Atenágoras, R. 56, 20.) Animal, especialmente animal selvagem, 1Cl 20:4. <span class=\"greek\">θῆρες</span> <span class=\"greek\">ἄγριοι</span>, «animais selvagens», 56:12 (Jó 5:23). — Schmidt, Syn. II 432–36; DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0169-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θήρα, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver <span class=\"greek\">θήρ</span>; Homero e posteriores; inscrições, papiros, LXX; TestZeb; Fílon, Mos. 1, 298; Josefo, Ant. 1, 274; 18, 45, geralmente no sentido de «caça» ou «presa».) Rede, armadilha (assim Horapolo 2, 26 com <span class=\"greek\">παγίς</span>; Sl 34:8; Pv 11:8), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 11:9</a>. — DELG, s.v. <span class=\"greek\">θήρ</span>; M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0169-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηρεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">1º aoristo <span class=\"greek\">ἐθήρευσα</span> (ver <span class=\"greek\">θήρ</span>; Homero e outros; inscrições, papiros, LXX; TestZeb 5:5; Aristides 11, 2). Caçar, capturar; figuradamente (em diversos empregos desde Píndaro e outros; Diodoro Sículo 2, 5, 1; Sl 139:12; Fílon; Josefo, Ant. 19, 308): <span class=\"greek\">θ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">στόματος</span> <span class=\"greek\">αὐτοῦ</span>, «apanhá-lo em alguma coisa que viesse a dizer», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.54\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:54</a> (Platão, Gorg. 489b <span class=\"greek\">ὀνόματα</span> <span class=\"greek\">θηρεύειν</span>, «caçar as palavras [dos outros] para ver se acaso cometem erros» [<span class=\"greek\">ἐάν</span> <span class=\"greek\">τις</span> <span class=\"greek\">ῥήματι</span> <span class=\"greek\">ἀμάρτῃ</span>]. — <span class=\"greek\">θ</span>., «capturar por traição», Pseudo-Clemente, Hom. 8, 22). <span class=\"greek\">τίς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θηρεύσας</span> <span class=\"greek\">με</span>; «Quem me enganou?», GJs 13:1. — DELG, s.v. <span class=\"greek\">θήρ</span>; M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0169-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηριομαχέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver <span class=\"greek\">θηρίον</span>, <span class=\"greek\">μάχομαι</span>.) 1º aoristo <span class=\"greek\">ἐθηριομάχησα</span>.</p><p class=\"entry-text\">① Ser obrigado a combater feras como punição; lutar contra animais selvagens (Diodoro Sículo 3, 43, 7; Artemidoro 2, 54; 5, 49; Ptolomeu, Apotel. 4, 9, 10; Vécio Valente 129, 33; 130, 21; Josefo, Bell. 7, 38), IEph 1:2; ITr 10; <span class=\"greek\">ἐπισήμως</span> <span class=\"greek\">θ</span>., «combater feras publicamente», MPol 3, 1. Sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.32\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15:32</a>, ver 2.</p><p class=\"entry-text\">② Encontrar-se em situação de ter de enfrentar adversários: lutar contra, contender com. É incerto se <span class=\"greek\">θ</span>. é empregado literalmente ou figuradamente em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.32\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15:32</a>. É bastante improvável que Paulo tenha realmente lutado com feras (mas ver Bowen abaixo). Ele nada diz dessa experiência em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.23-29\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 11:23–29</a>, e Atos tampouco a menciona (embora Atos silencie sobre numerosos assuntos). Além disso, o apóstolo não poderia ter sido condenado ad bestias sem perder a cidadania romana que ainda possuía posteriormente e que serviu de fundamento para seu recurso ao imperador.</p><p class=\"entry-text\">Se, não obstante, o verbo for entendido literalmente, a expressão deve ser considerada (com J. Weiss sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.32\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15:32</a> e W. Michaelis, Die Gefangenschaft d. Paulus in Ephesus, 1925, 118ss.) uma oração condicional contrária ao fato (irreal): «se eu tivesse lutado com feras» (contra essa interpretação, J. Schmid, Zeit u. Ort d. paul. Gefangenschaftsbr., ’31, 39–60; W. Kümmel, Hdb., ’49).</p><p class=\"entry-text\">Mas a expressão pode também ser figurada (frequente na diatribe cínico-estoica; A. Malherbe, JBL 87, ’68, 71–80), como certamente ocorre em IRo 5:1: <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">Συρίας</span> <span class=\"greek\">μέχρι</span> <span class=\"greek\">Ῥώμης</span> <span class=\"greek\">θηριομαχῶ</span> … <span class=\"greek\">δεδεμένος</span> <span class=\"greek\">δέκα</span> <span class=\"greek\">λεοπάρδοις</span>, <span class=\"greek\">ὅ</span> <span class=\"greek\">ἐστι</span> <span class=\"greek\">στρατιωτικὸν</span> <span class=\"greek\">τάγμα</span>, «da Síria até Roma luto contra feras, acorrentado a dez leopardos, isto é, a um destacamento de soldados» (cf. OGI 201, 16 <span class=\"greek\">ἐπολέμησα</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">Π</span>. <span class=\"greek\">ἕως</span> <span class=\"greek\">Τ</span>.). Aqui Inácio descreve os sofrimentos de sua viagem como prisioneiro com uma palavra que sugere a luta contra feras (cf. Apiano, Bell. Civ. 2, 61 §252, em que Pompeu diz, em linguagem figurada semelhante: <span class=\"greek\">οἵοις</span> <span class=\"greek\">θηρίοις</span> <span class=\"greek\">μαχόμεθα</span>; Fílon, Mos. 1, 43s.). Inácio desejava que animais selvagens de verdade o devorassem, IRo 4:1s.; 5:2.</p><p class=\"entry-text\">Em AcPl Ha 3, 9; 4, 8; 5, 13, referem-se combates reais com feras (latim venationes). — C. Bowen, JBL 42, 1923, 59–68; C. Coffin, ibid. 43, 1924, 172–76; J. Hunkin, ET 39, 1928, 281s.; R. Osborne, JBL 85, ’66, 225–30; bibliografia em <span class=\"greek\">ἀγών</span>. — DELG, s.v. <span class=\"greek\">θήρ</span>; M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0169-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηριομαχίον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver verbetes anterior e seguinte; TAM II, 508, 12.) Plural <span class=\"greek\">τὰ</span> <span class=\"greek\">θ</span>. (cf. Cícero, Ep. 70, 20; 22, ludus bestiarius. O combate habitualmente colocava os condenados contra leões, tigres, leopardos, lobos ou cães.) Combate com feras, AcPl Ha 2, 11; 36, 3 e 17. — Cf. DELG, s.v. <span class=\"greek\">θήρ</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0169-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηριομάχος, ον</h1><div class=\"entry-meta\"><span>adjetivo de dois gêneros</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Marco Aurélio 10, 87 e outros.) Que luta com animais selvagens: <span class=\"greek\">τῷ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">ἀνθρώπῳ</span>, AcPl Ha 5, 30. Substantivado: <span class=\"greek\">τοῦ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">λόγον</span>, AcPl Ha 2, 14. — DELG, s.v. <span class=\"greek\">θήρ</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0169-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θηρίον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Homero e posteriores.) Formalmente, mas nem sempre semanticamente, diminutivo de <span class=\"greek\">θήρ</span>.</p><p class=\"entry-text\">① Qualquer criatura viva, excluídos os seres humanos: animal, fera.</p><p class=\"entry-text\">ⓐ A respeito de animais reais.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Em geral, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:20</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span> (Gn 1:24, 25, 30), B 6:12; cf. v. 18; GJs 3:2; <span class=\"greek\">τῆς</span> <span class=\"greek\">θαλάσσης</span>, B 4:5 (Dn 7:7). Com adjetivo, <span class=\"greek\">θ</span>. <span class=\"greek\">ἄγρια</span> (Xenofonte, An. 1, 2, 7; TestSol 10, 3 C), 1Cl 56:11 (Jó 5:22).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. De animais de determinada espécie.</p><p class=\"entry-text\">א . Quadrúpedes enquanto tais (Pseudo-Clemente, Hom. 3, 36): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 3:7</a>; <span class=\"greek\">φυλακὴ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">θηρίου</span> <span class=\"greek\">ἀκαθάρτου</span>, «jaula de toda espécie de animal impuro», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 18:2</a>.</p><p class=\"entry-text\">ב . Animais selvagens (Diodoro Sículo 1, 87, 3; Josefo, Bell. 3, 385; Ant. 9, 197), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1:13</a> (F. Spitta, ZNW 5, 1904, 323ss.; 8, 1907, 66ss. — Himério, Or. 39 [= Or. 5], 5: Orfeu, nas montanhas da Trácia, sem ninguém que o ouça, <span class=\"greek\">θηρίων</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐκκλησίαν</span> <span class=\"greek\">ἐργάζεται</span>, «forma para si uma comunidade de animais selvagens»); talvez também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.6\" target=\"_blank\" rel=\"noopener noreferrer\">At 11:6</a> (ver Hs 9, 26, 1, abaixo). — 1689–92.</p><p class=\"entry-text\">ג . Com ênfase no aspecto do perigo: em geral (Antígono de Caristo 29 [lobo]; Diodoro Sículo 17, 92, 2 e 3 [leão]; Máximo de Tiro 20, 2b; Josefo, Ant. 2, 35), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 6:8</a> (cf. Heródoto 6, 44, 3); IEph 7:1.</p><p class=\"entry-text\">ד . Réptil, serpente (Diodoro Sículo 20, 42, 2, alternando com <span class=\"greek\">ὄφις</span>; Polieno 2, 3, 15 com <span class=\"greek\">ἔχις</span>; Areteu 159, 8 <span class=\"greek\">τὸ</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θηρίων</span> <span class=\"greek\">φάρμακον</span>; 163, 2; Justino, A I, 60, 2; Galeno IV 779 K.; <span class=\"greek\">θήρ</span> = «serpente»: Símias [séc. III a.C.], Coll. Alex. Fgm. 26, 17 p. 119), At 28:4s.; Hs 9, 26, 7b; também ibid. 7a e provavelmente 9, 26, 1, com <span class=\"greek\">ἑρπετά</span> (cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.6\" target=\"_blank\" rel=\"noopener noreferrer\">At 11:6</a>; Josefo, Ant. 17, 117). Cf. PtK 2 p. 14, 18.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Frequentemente, animais selvagens em ambiente controlado, a saber, os confrontos com feras numa arena (Diodoro Sículo 36, 10, 3; Artemidoro 2, 54; Josefo, Bell. 7, 38), IRo 4:1s.; 5:2s.; ISm 4:2a, b; MPol 3:1; 4; 11:1s.; Dg 7:7; Hv 3, 2, 1; AcPl Ha 1, 28; 2, 4; 5, 5 e 9. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">θηρία</span> <span class=\"greek\">κατακρίνεσθαι</span>, «ser condenado a combater feras», MPol 2:4. <span class=\"greek\">κατέκρινεν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">θηρία</span>, AcPl Ha 1, 29.</p><p class=\"entry-text\">ⓑ A respeito de seres semelhantes a animais, mas de natureza transcendente (Pausânias 1, 24, 6, grifos; 2, 37, 4, a hidra; cf. Dn 7:3ss.), B 4:5 (Dn 7:7). De um dragão monstruoso (escólio a Apolônio de Rodes 4, 156–66a, o guardião do velocino de ouro; Damáscio, Vi. Isid. 140), Hv 4, 1, 6; 4, 1, 8; 4, 1, 10; 4, 2, 1; 4, 2, 3ss.; 4, 3, 1 e 7 (sobre o monstro em H, ver Joly p. 113, nota 2). As «feras» ou «bestas» do Apocalipse: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 11:7</a>; 13:1ss., 11s., 14s., 17s.; 14:9, 11; 15:2; 16:2, 10, 13; 17:3, 7s., 11ss., 16s.; 19:19s.; 20:4, 10. — Bibliografia em <span class=\"greek\">δράκων</span>. B. Murmelstein, StKr 101, 1929, 447–57; R. Schütz, D. Offb. d. Joh. u. Kaiser Domitian, ’33; P. Minear, JBL 72, ’53, 93–101.</p><p class=\"entry-text\">② Pessoa perversa, alguém de natureza «bestial»: fera, monstro; extensão figurada do sentido 1 (Aristófanes, Equ. 273; Plutus 439; Nub. 184; Apiano [ver <span class=\"greek\">θηριομαχέω</span>, fim]; Alcífron 2, 17, 4 e outros; Aquiles Tácio 6, 12, 3; Josefo, Bell. 1, 624; 627; Ant. 17, 117 e 120; cf. Vécio Valente 78, 9; BGU 1024 IV, 5ss.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 1:12</a> (Damáscio, Vi. Isid. 301, chama a esposa de Isidoro de <span class=\"greek\">κακὸν</span> <span class=\"greek\">θ</span>.). <span class=\"greek\">θ</span>. <span class=\"greek\">ἀνθρωπόμορφα</span>, «feras em forma humana» (Fílon, Ab. 33), ISm 4:1. — B. 137; DELG, s.v. <span class=\"greek\">θήρ</span>; 1689–92; M-M; EDNT; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0169-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θησαυρίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">1º aoristo <span class=\"greek\">ἐθησαύρισα</span>; particípio perfeito passivo <span class=\"greek\">τεθησαυρισμένος</span> (ver verbete seguinte; Heródoto e outros; SIG 954, 80; LXX; En 97:9; PsSol 9:5; Fílon).</p><p class=\"entry-text\">① Manter em segurança algum bem material mediante armazenamento: guardar, acumular, reunir, poupar. Com acusativo <span class=\"greek\">τὶ</span>, «alguma coisa» (Diodoro Sículo 5, 21, 5; 20, 8, 4), <span class=\"greek\">ὅ</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἐὰν</span> <span class=\"greek\">εὐοδῶται</span>, «de acordo com seus ganhos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 16:2</a>. Com duplo complemento <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span>, «algo para alguém»: <span class=\"greek\">θησαυροὺς</span> <span class=\"greek\">ἑαυτῷ</span>, «acumular tesouros para si mesmo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:19</a> (citado em Justino, A I, 15, 11). Emprego absoluto (Filodemo, Oec. p. 71 Jensen; Sl 38:7; Justino, A I, 15, 12 [sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:20</a>?]), «acumular tesouros», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 5:3</a>. Com dativo <span class=\"greek\">τινὶ</span>, «para alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 12:14</a>.</p><p class=\"entry-text\">② Fazer algo que produzirá um acontecimento ou estado futuro: armazenar, acumular; extensão figurada do sentido 1 (Diodoro Sículo 9, 10, 3: palavras <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ψυχαῖς</span> <span class=\"greek\">τεθησαυρισμέναι</span>; Filóstrato, Vi. Soph. 2, 1, 2 <span class=\"greek\">θ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">γνώμαις</span>, «nos corações»).</p><p class=\"entry-text\">ⓐ Acerca de tesouros no céu (cf. Tb 4:9; PsSol 9:5 <span class=\"greek\">θ</span>. <span class=\"greek\">ζωὴν</span> <span class=\"greek\">αὑτῷ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">κυρίῳ</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:20</a> (citado em Justino, A I, 15, 11; cf. 12 [citação?]).</p><p class=\"entry-text\">ⓑ Acumular abundantemente <span class=\"greek\">ὀργὴν</span> <span class=\"greek\">ἑαυτῷ</span>, «ira contra si mesmo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2:5</a> (cf. Diodoro Sículo 20, 36, 4 <span class=\"greek\">φθόνος</span>; Apiano, Samn. 4, 3; Vi. Aesopi G 107 P. <span class=\"greek\">κακά</span>; IPriene 112, 15 <span class=\"greek\">ἐθησαύρισεν</span> <span class=\"greek\">ἑαυτῷ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ζώντων</span> <span class=\"greek\">ἔπαινον</span>, <span class=\"greek\">παρὰ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἐπεσομένων</span> <span class=\"greek\">μνήμην</span>, «acumulou para si elogios dos vivos e lembrança entre os que ainda nascerão»; Pv 1:18 <span class=\"greek\">κακά</span>. Ver também <span class=\"greek\">ὀργή</span> 2b; sobre <span class=\"greek\">θ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμ</span>., cf. Tb 4:9).</p><p class=\"entry-text\">ⓒ Guardar, reservar (4Mc 4:3; Fílon, Sacr. Abel. 62; Deus Imm. 156): céu e terra <span class=\"greek\">τεθησαυρισμένοι</span> <span class=\"greek\">εἰσίν</span>, «estão reservados», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 3:7</a>. — DELG, s.v. <span class=\"greek\">θησαυρός</span>; M-M; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0169-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θησαυρός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver verbete precedente; Hesíodo, Heródoto e posteriores; empréstimo no hebraico rabínico; <span class=\"greek\">τὴν</span> <span class=\"greek\">θ</span>. TestSol 13:2 C).</p><p class=\"entry-text\">① Lugar onde algo é conservado em segurança, depósito, repositório (Teófilo de Antioquia 2, 35 [p. 188, 16]).</p><p class=\"entry-text\">ⓐ Depósitos de bens materiais.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Arca ou cofre de tesouros (cf. Xenofonte, An. 5, 4, 27; Diodoro Sículo 17, 71, 1; PTebt 6, 27; PAmh 41, 8; En 97:9; Josefo, Ant. 9, 163), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:11</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Armazém, depósito, despensa (Apiano, Fgm. 6; PRyl 231, 8; PFay 122, 4; POxy 101, 29; Am 8:5; Pv 8:21), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.52\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:52</a> (sobre <span class=\"greek\">ἐκβάλλειν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θ</span>., cf. Arriano, Cyneg. 34, 1 <span class=\"greek\">ἐμβάλλειν</span> <span class=\"greek\">ἐς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θ</span>.).</p><p class=\"entry-text\">ⓑ Depósitos de coisas transcendentes (TestAsh 1:9): o coração como tesouro ou repositório de bens celestes, <span class=\"greek\">θ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">καρδίας</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:45</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:35</a> (sobre <span class=\"greek\">ἀγαθὸς</span> <span class=\"greek\">θ</span>., ver Dt 28:12). — G. Kaminski, JDAI 106, ’91, 63–181 (inscrições); ver SEG XLI, 1846.</p><p class=\"entry-text\">② Aquilo que se conserva guardado, tesouro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:34</a> (cf. Justino, A I, 15, 16).</p><p class=\"entry-text\">ⓐ De coisas materiais (TestSol C 10, 21 e outros; Diodoro Sículo 17, 71, 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:19</a>; 13:44 (sobre tesouro <span class=\"greek\">θ</span>. enterrado: Máximo de Tiro 15, 5h; Artemidoro 2, 58; Filóstrato, Vi. Apoll. 6, 39 p. 250, 4ss.; J. Derrett, Law in the NT, ’70, 1–16). Os tesouros do Egito, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:26</a>.</p><p class=\"entry-text\">ⓑ De coisas transcendentes (Irineu 4, 26, 1 [Harvey II 235, 9]; sobre <span class=\"greek\">θ</span>. desenterrado em sentido metafórico, cf. Filêmon Cômico 169 <span class=\"greek\">Κ</span>. <span class=\"greek\">ἐὰν</span> <span class=\"greek\">γυνὴ</span> <span class=\"greek\">γυναικὶ</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἰδίαν</span> <span class=\"greek\">ὁμιλεῖ</span>, <span class=\"greek\">μεγάλων</span> <span class=\"greek\">κακῶν</span> <span class=\"greek\">θησαυρὸς</span> <span class=\"greek\">ἐξορύσσεται</span>. Uso metafórico também no final de b<span class=\"greek\">γ</span>).</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Tesouros no céu, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:20</a>. <span class=\"greek\">θ</span>. <span class=\"greek\">ἀνέκλειπτος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οὐρανοῖς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:33</a>. <span class=\"greek\">θησαυρὸν</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">οὐρανῷ</span>, «ter um tesouro no céu»; na prática, o tesouro está depositado ali e se torna acessível às pessoas depois da morte, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 18:22</a>. — W. Pesch, Biblica 41, ’60, 356–78 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.19-21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:19–21</a>; Lc 12:33s.).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. <span class=\"greek\">θησαυροὶ</span> <span class=\"greek\">σκοτεινοί</span>, «tesouros ocultos nas trevas», B 11:4 (Is 45:3).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Acerca do evangelho e de sua glória, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 4:7</a>. Acerca de Cristo: <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">εἰσιν</span> <span class=\"greek\">πάντες</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">θησαυροὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σοφίας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">γνώσεως</span> <span class=\"greek\">ἀπόκρυφοι</span>, «em quem estão ocultos todos os tesouros da sabedoria e do conhecimento», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:3</a> (<span class=\"greek\">ἐν</span> <span class=\"greek\">θησαυροῖς</span> <span class=\"greek\">σοφίας</span>, Sir 1:25; cf. Xenofonte, Mem. 1, 6, 14; 4, 2, 9 <span class=\"greek\">θησαυροὶ</span> <span class=\"greek\">σοφίας</span>; Platão, Phileb. 15e; Diodoro Sículo 9, 10, 3 <span class=\"greek\">κάλλιστος</span> <span class=\"greek\">θ</span>.; Himério, Or. [Ecl.] 3, 20 <span class=\"greek\">θ</span>. <span class=\"greek\">ἀθάνατος</span>, sobre a posse da virtude; Pv 2:3ss.; Fílon, Congr. Erud. Gr. 127). — B. 777; BHHW III 1686; DELG; M-M; EDNT; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0169-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θιγγάνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">2º aoristo <span class=\"greek\">ἔθιγον</span> (autores trágicos e outros, mas não na prosa ática [W. Rutherford, New Phryn., 1881, 169s.; 391]; Hipócrates [Anz 293]; inscrições, papiros; Êx 19:12; JosAs16 [p. 64, linha 20 Bat.], códice A [<span class=\"greek\">ἔθηξε</span>, proveniente da forma paralela <span class=\"greek\">θίγω</span>]). Tocar, com genitivo <span class=\"greek\">τινός</span>, «alguma coisa» (Ésquilo e outros; EpArist 106), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:20</a> (cf. Díon Crisóstomo 31, 10). Em sentido hostil, com genitivo <span class=\"greek\">τινός</span>, «alguém» (Eurípides, Iph. A. 1351; acerca do que causa dano moral, AcThom 12 [Aa II/2, 118, 5] <span class=\"greek\">παῖδες</span>, <span class=\"greek\">ὧν</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">βλάβαι</span> <span class=\"greek\">αὗται</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">θιγγάνουσι</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:28</a>. Uso absoluto: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:21</a> (IG XII/3, 451 <span class=\"greek\">μὴ</span> <span class=\"greek\">θίγγανε</span>); mas ver <span class=\"greek\">ἅπτω</span> 3. — Cf. <span class=\"greek\">ψηλαφάω</span>; ver Schmidt, Syn. I 228–43; DELG; M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0169-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θλάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Imperfeito, 3ª pessoa do plural <span class=\"greek\">ἔθλων</span>, PsSol 13:3; futuro <span class=\"greek\">θλάσω</span>; 1º aoristo <span class=\"greek\">ἔθλασα</span>; perfeito <span class=\"greek\">τέθλακα</span>. Passiva: aoristo, 2ª pessoa do singular <span class=\"greek\">ἐθλάσθης</span>, Ez 29:7; particípio perfeito <span class=\"greek\">τεθλασμένος</span>, LXX (Homero e outros; PFay 112, 20 [99 d.C.]; PsSol 13:3; Josefo, Ant. 10, 7 = 4Km 18:21). Quebrar um selo (o que, nesse caso, não é um ato natural e intencional, mas um acontecimento profundamente lamentável, pois o selo aparece como meio de proteção e sua destruição é seguida de consequências terríveis), Hs 8, 6, 3. — DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0169-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θλίβω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Futuro <span class=\"greek\">θλίψω</span>; 1º aoristo <span class=\"greek\">ἔθλιψα</span>. Passiva: futuro, 3ª pessoa do singular <span class=\"greek\">θλιβήσεται</span>, Jó 20:22; 2º aoristo <span class=\"greek\">ἐθλίβην</span>; particípio perfeito <span class=\"greek\">τεθλιμμένος</span> (ver verbete seguinte; Homero e posteriores; inscrições, papiros, LXX, pseudoepígrafos; Fílon; Josefo, Bell. 3, 330; Ant. 20, 111; SibOr; Melitão, P. 80, 587).</p><p class=\"entry-text\">① Apertar ou comprimir contra alguém, pressionar, aglomerar-se junto de; com acusativo <span class=\"greek\">τινά</span>, «alguém» (Sir 16:28, variante de leitura; JosAs 23:8 <span class=\"greek\">τὸν</span> <span class=\"greek\">πόδα</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3:9</a> (cf. Apiano, Bell. Civ. 4, 45 §194 <span class=\"greek\">ἐπιθλίβω</span> <span class=\"greek\">τινά</span>, «comprimir alguém em meio à multidão»).</p><p class=\"entry-text\">② Fazer alguma coisa ficar comprimida ou estreita: pressionar, comprimir, estreitar (Dionísio de Halicarnasso 8, 73 <span class=\"greek\">βίοι</span> <span class=\"greek\">τεθλιμμένοι</span>, «provisões que se tornaram escassas»; <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἔθλιψεν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σελήνην</span>, GrBar 9:7). Na passiva, de espaço limitado (Teócrito 21, 18 <span class=\"greek\">θλιβομένα</span> <span class=\"greek\">καλύβα</span>, «moradia apertada»; Luciano, Alex. 49 <span class=\"greek\">τ</span>. <span class=\"greek\">πόλεως</span> <span class=\"greek\">θλιβομένης</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πλήθους</span>, «a cidade apinhada pela multidão»): <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> <span class=\"greek\">τόπῳ</span> <span class=\"greek\">τεθλιμμένῳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πεπληρωμένῳ</span> <span class=\"greek\">ἑρπετῶν</span> <span class=\"greek\">πονηρῶν</span>, «em lugar apertado e cheio de serpentes malignas», isto é, inteiramente apinhado de serpentes malignas, ApcPt 10:25 (o sofrimento é duplo: o espaço já é exíguo e a pessoa está completamente cercada por serpentes).</p><p class=\"entry-text\">Sobre uma estrada (com a correspondente <span class=\"greek\">στενὴ</span> <span class=\"greek\">πύλη</span>), <span class=\"greek\">ὁδὸς</span> <span class=\"greek\">τεθλιμμένη</span>, «caminho estreito, apertado» e, por isso, fonte de dificuldades para os que o percorrem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:14</a> (TestAbr A 11 p. 88, 30 [Stone p. 24]; ver K. Bornhäuser, Die Bergpredigt, 1923, 177ss.); sobre a imagem, ver A. Mattill, JBL 98, ’79, 531–46; Betz, SM 527: «As possibilidades de fracasso são maiores que as de êxito, uma mensagem que incita à sobriedade».</p><p class=\"entry-text\">③ Causar perturbação: oprimir, afligir; com acusativo <span class=\"greek\">τινά</span>, «alguém» (Dt 28:53; Lv 19:33; SibOr 3, 630), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 1:6</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἅγιον</span>, «oprimir o Espírito Santo», Hm 10, 2, 5; <span class=\"greek\">χρεώστας</span> <span class=\"greek\">θ</span>., «oprimir devedores», Hm 8:10.</p><p class=\"entry-text\">Na passiva: ser afligido, atribulado (UPZ 42, 22 [162 a.C.]; PsSol 1:1 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1:6</a>; 4:8; 7:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.37\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:37</a>; Hm 2:5. <span class=\"greek\">θλιβείς</span>, «por meio do sofrimento», B 7:11. <span class=\"greek\">θλιβεὶς</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">γνώμῃ</span> <span class=\"greek\">τινός</span>, «afligido pela maquinação de alguém», IPhld 6:2. <span class=\"greek\">ψυχὴ</span> <span class=\"greek\">θλιβομένη</span>, «alma aflita», Hs 1:8 (PGM 1, 213 <span class=\"greek\">θλίβεταί</span>[?] <span class=\"greek\">μου</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ψυχή</span>; TestSol 1:4 <span class=\"greek\">θλιβομένης</span> <span class=\"greek\">μου</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ψυχῆς</span>; Melitão, P. 80, 587; Proclo, sobre Platão, Crat. 72, 3 Pasqu. <span class=\"greek\">δαίμονες</span> <span class=\"greek\">θλίβουσι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ψυχάς</span>; Nicetas Eugêniano 2, 27 H. <span class=\"greek\">ψυχὴ</span> <span class=\"greek\">τεθλιμμένη</span>; cf. Fílon, De Ios. 179). Sobre Hs 8, 10, 4, ver Bonner 113, nota.</p><p class=\"entry-text\">Substantivado: <span class=\"greek\">ὁ</span> <span class=\"greek\">θλιβόμενος</span>, «o oprimido» (TestSol D 4, 11 <span class=\"greek\">παραμυθία</span> <span class=\"greek\">των</span> <span class=\"greek\">θ</span>.; JosAs 12:11 <span class=\"greek\">τῶν</span> <span class=\"greek\">θλιβομένων</span> <span class=\"greek\">βοηθός</span>; Diodoro Sículo 13, 109, 5 <span class=\"greek\">οἱ</span> <span class=\"greek\">θλιβόμενοι</span>, «os que se encontravam sob intensa pressão»), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 5:10</a>; ISm 6:2; B 20:2; D 5:2. Especialmente, como em algumas das passagens citadas, da perseguição aos cristãos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 3:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 1:7</a>. <span class=\"greek\">θλιβῆναι</span> <span class=\"greek\">πάσῃ</span> <span class=\"greek\">θλίψει</span>, «sofrer toda espécie de aflição», Hs 6, 3, 6; cf. 7:1ss.; 8, 10, 4. <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νόμου</span> <span class=\"greek\">θλιβέντες</span>, «perseguidos por causa da lei» (isto é, por uma maneira de viver conforme os ensinamentos de Jesus), Hs 8, 3, 7. — DELG; M-M; EDNT; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0169-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θλῖψις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver <span class=\"greek\">θλίβω</span>; sobre a acentuação, ver B-D-F §13; W-S. §6, 3c; Mlt-H. 57. — K. Lipsius, Grammat. Untersuchungen über d. bibl. Gräz., 1863, 34s., prefere escrever <span class=\"greek\">θλίψις</span>; também W-H.) Rara no grego extrabíblico e, nesse âmbito, literalmente «aperto, pressão» (Aristóteles, Meteorol. 4, 4, 383a, 13; Epicuro p. 45, 9 Us.; Pseudo-Aristóteles, De Mundo 4, 394a, 29; Estrabão; Galeno).</p><p class=\"entry-text\">① Na literatura considerada (assim como na LXX, En, Test12Patr, JosAs, códice A; Justino, D. 116, 2; Melitão), frequente em sentido metafórico: tribulação que causa sofrimento, opressão, aflição, angústia (assim Vécio Valente 71, 16; Cat. Cod. Astr. VIII/3 p. 175, 5; 178, 8; plural 169, 2 [ver Boll 134s.]; OGI 444, 15 [séc. II ou I a.C.] <span class=\"greek\">διὰ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πόλεων</span> <span class=\"greek\">θλίψεις</span>; BGU 1139, 4 [séc. I a.C.]; POxy 939, 13; PAmh 144, 18).</p><p class=\"entry-text\">Da aflição causada por circunstâncias exteriores (Josefo, Ant. 4, 108; En, PsSol, Melitão; Dídimo, Gen. 116, 10), no singular e no plural: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 11:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 5:3b</a>; 12:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1:8</a>; 6:4; 8:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 1:9</a>; 2:9, 22; 1Cl 22:7 (Sl 33:18); 59:4; 2Cl 11:4 (citação de origem desconhecida); Hs 7:4ss. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πάσῃ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">ἡμῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1:4a</a>; 7:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 3:7</a>; <span class=\"greek\">ἐν</span> <span class=\"greek\">πάσῃ</span> <span class=\"greek\">θ</span>. (TestGad 4:4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1:4b</a>; <span class=\"greek\">ἐν</span> (<span class=\"greek\">τ</span>.) <span class=\"greek\">θ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 5:3a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 3:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 1:6</a>; 3:3. <span class=\"greek\">ἐν</span> <span class=\"greek\">πολλαῖς</span> <span class=\"greek\">θ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">ποικίλαις</span>, Hs 7, 4.</p><p class=\"entry-text\"><span class=\"greek\">θ</span>. <span class=\"greek\">μεγάλη</span>, «grande tribulação» (SibOr 3, 186), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:21</a> (1Mc 9:27); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:11</a>; Hv 4, 2, 4; no plural, Hv 3, 2, 1. <span class=\"greek\">ἡ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">ἡ</span> <span class=\"greek\">μεγάλη</span>, «a grande tribulação», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 7:14</a>; <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐλαφρὸν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θ</span>., «aflição leve», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 4:17</a>. <span class=\"greek\">ἀνταποδοῦναί</span> <span class=\"greek\">τινι</span> <span class=\"greek\">θλῖψιν</span>, «retribuir a alguém com aflição», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 1:6</a>. Com <span class=\"greek\">ἀνάγκη</span> (ver acepção 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 3:7</a>; com <span class=\"greek\">διωγμός</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.1\" target=\"_blank\" rel=\"noopener noreferrer\">At 8:1</a>, Códice D; 13:50, Códice D; no plural, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 1:4</a>. Com <span class=\"greek\">δεσμά</span> (TestJos 2:4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.23\" target=\"_blank\" rel=\"noopener noreferrer\">At 20:23</a>; com <span class=\"greek\">ὀνειδισμός</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.33\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:33</a>; com <span class=\"greek\">στενοχωρία</span> (ver respectivo verbete), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2:9</a>; com <span class=\"greek\">στενοχωρία</span> e <span class=\"greek\">διωγμός</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.35\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8:35</a> (com <span class=\"greek\">λιμός</span> e <span class=\"greek\">στενοχωρία</span>, Hipólito, Ref. 5, 26, 12).</p><p class=\"entry-text\">Sobre o catálogo de adversidades (perístase), cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.9-13\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 4:9–13</a>; 2Co 4:8s.; 6:4–10; 11:23–28; 12:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 4:11</a>; ver F. Danker, Augsburg Comm. 2 Cor, ’89, 89–91; 180s.; idem, The Endangered Benefactor in Luke-Acts: SBLSP, ’81, 39–48; J. Fitzgerald, Cracks in an Earthen Vessel, ’88; M. Ferrari, Die Sprache des Leids in den paulinischen Persistasen-katalogen, ’91; M. Ebner, Leidenslisten u. Apostelbrief, ’91. — <span class=\"greek\">ἡμέρα</span> <span class=\"greek\">θλίψεως</span>, «dia de aflição» (Gn 35:3; 2Km 22:19; cf. En 103:9; TestLevi 5:5), 1Cl 52:3 (Sl 49:15).</p><p class=\"entry-text\">Das tribulações dos últimos dias (como em Dn 12:1): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:21</a>, 29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13:19</a>, 24. <span class=\"greek\">ἡ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐρχομένη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">μεγάλη</span>, «a grande tribulação vindoura», Hv 2, 2, 7; cf. 2, 3, 4; 4, 1, 1; 4, 2, 5; 4, 3, 6. Aflição ocasionada pela guerra, 1Cl 57:4 (Pv 1:27). <span class=\"greek\">θ</span>. <span class=\"greek\">θανάτου</span>, «aflição da morte», B 12:5. Circunstâncias difíceis, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.13\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 8:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1:27</a>; <span class=\"greek\">συγκοινωνεῖν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">θ</span>., «demonstrar participação na aflição [de alguém]», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 4:14</a>. Das dores de parto de uma mulher, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.21\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 16:21</a>.</p><p class=\"entry-text\"><span class=\"greek\">ὅταν</span> <span class=\"greek\">γένηται</span> <span class=\"greek\">θ</span>., «quando sobrevier perseguição», Hv 3, 6, 5. <span class=\"greek\">θλῖψιν</span> <span class=\"greek\">ἀκούειν</span>, «ouvir falar de perseguição», Hs 9, 21, 3. <span class=\"greek\">θλῖψιν</span> <span class=\"greek\">ἔχειν</span>, «ter aflição», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.33\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 16:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.28\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 7:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2:10</a>; Hv 2, 3, 1; Hs 7:3. <span class=\"greek\">ἐὰν</span> <span class=\"greek\">ὑπενέγκῃ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">θλίψεις</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐπερχομένας</span> <span class=\"greek\">αὐτῷ</span>, Hs 7:4; cf. 7:6. <span class=\"greek\">ἐξείλατο</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">πασῶν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">θλίψεων</span> <span class=\"greek\">αὐτοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:10</a>. <span class=\"greek\">διὰ</span> <span class=\"greek\">πολλῶν</span> <span class=\"greek\">θ</span>. <span class=\"greek\">εἰσελθεῖν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">βασιλείαν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 14:22</a>. <span class=\"greek\">τότε</span> <span class=\"greek\">παραδώσουσιν</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">θλῖψιν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:9</a>; cf. B 12:5. <span class=\"greek\">ἀποστήσεται</span> <span class=\"greek\">πᾶσα</span> <span class=\"greek\">θ</span>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">σοῦ</span> … <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">ἀποστήσεται</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">θ</span>., Hs 7, 7. Dos sofrimentos de Cristo: <span class=\"greek\">θλίψεις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:24</a> (ver <span class=\"greek\">ἀνταναπληρόω</span> e <span class=\"greek\">πάθημα</span> 1).</p><p class=\"entry-text\">② Experiência interior de sofrimento, aflição, angústia (Gn 35:3; 42:21 <span class=\"greek\">θ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ψυχῆς</span>): <span class=\"greek\">θ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">συνοχὴ</span> <span class=\"greek\">καρδίας</span>, «aflição e angústia do coração», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 2:4</a>. <span class=\"greek\">θλῖψιν</span> <span class=\"greek\">ἐγείρειν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">δεσμοῖς</span> <span class=\"greek\">μου</span>, «causar-me sofrimento em meu aprisionamento», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1:17</a>. <span class=\"greek\">Ἅννα</span> … <span class=\"greek\">περιείλατο</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">θλῖψιν</span> <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">αὐτῆς</span>, «Ana ... afastou de si toda aflição», GJs 2:4 (códice A, não o papiro; ver <span class=\"greek\">περιαιρέω</span> 1). — DELG, s.v. <span class=\"greek\">θλίβω</span>; M-M; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0169-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θνῄσκω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver verbete seguinte e <span class=\"greek\">ἀποθνῄσκω</span>; Homero e posteriores. Sobre a grafia, ver Kühner-Bl. I 133; II 442; B-D-F §26 e 27; W-S. §5, 11b; Mlt-H. 84.) Futuro, 3ª pessoa do singular <span class=\"greek\">θανεῖται</span>, Pv 13:14; 2º aoristo <span class=\"greek\">ἔθανον</span>, LXX; perfeito <span class=\"greek\">τέθνηκα</span>; infinitivo <span class=\"greek\">τεθνηκέναι</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 14:19</a>, variante <span class=\"greek\">τεθνάναι</span>, como em Josefo, Vi. 59); particípio <span class=\"greek\">τεθνηκώς</span> (LXX; <span class=\"greek\">τεθνεώς</span>, Taciano; <span class=\"greek\">τεθνηῶτες</span>, Jó 39:30). Formações analógicas: 3º futuro médio, 1ª pessoa do plural <span class=\"greek\">τεθνηξόμεθα</span>, 4Mc 8:21 (sobre esse futuro, ver Schwyzer I 783, especialmente nota 3), e particípio aoristo acusativo plural <span class=\"greek\">τεθνήξαντας</span> (TestAbr A 18 p. 100, 27 [Stone p. 48]); mais-que-perfeito, 3ª pessoa do singular <span class=\"greek\">ἐτεθνήκει</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11:21</a>, variante de leitura; 2ª pessoa do plural <span class=\"greek\">τεθνήκειτε</span>, Hs 9, 28, 6. Em geral, «morrer»; no perfeito, «ter morrido, estar morto».</p><p class=\"entry-text\">① Passar da vida física para a morte: morrer, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:49</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.33\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 19:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 14:19</a>; 25:19. Particípio perfeito substantivado: «ter morrido, estar morto»; (<span class=\"greek\">ὁ</span>) <span class=\"greek\">τεθνηκώς</span>, «o homem que havia morrido» (uso clássico; LXX), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.44\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11:44</a>; 12:1, variante de leitura.</p><p class=\"entry-text\">② Perder a relação com Deus: morrer, extensão figurada do sentido 1 (com <span class=\"greek\">ζῆν</span>: Cáriton 7, 5, 4), sobre a morte espiritual (Élio Aristides 52, 2 K. = 28 p. 551 D.: <span class=\"greek\">τὸ</span> <span class=\"greek\">τεθνηκὸς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ψυχῆς</span>; Bar 3:4; Fílon, Fug. 55 <span class=\"greek\">ζῶντες</span> <span class=\"greek\">ἔνιοι</span> <span class=\"greek\">τεθνήκασι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τεθνηκότες</span> <span class=\"greek\">ζῶσι</span>): <span class=\"greek\">ζῶσα</span> <span class=\"greek\">τέθνηκεν</span>, «está morta embora ainda viva», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 5:6</a>. (Timocles Cômico [séc. IV a.C.] 35 <span class=\"greek\">οὗτος</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">ζώντων</span> <span class=\"greek\">τεθνηκώς</span>, «morto entre os vivos».) <span class=\"greek\">οὔτε</span> <span class=\"greek\">ζῶσιν</span> <span class=\"greek\">οὔτε</span> <span class=\"greek\">τεθνήκασιν</span>, Hs 8, 7, 1; 9, 21, 2; cf. 9, 21, 4. <span class=\"greek\">διὰ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἁμαρτίας</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">τεθνήκειτε</span> [<span class=\"greek\">ἂν</span>] <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>, «por causa de vossos pecados, teríeis morrido para Deus», Hs 9, 28, 6. — DELG, s.v. <span class=\"greek\">θάνατος</span>; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0169-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θνητός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver verbete precedente e <span class=\"greek\">ἀποθνῄσκω</span>; Homero e outros; SIG 798, 10 [37 d.C.]; LXX; TestSol 4, 11 D; ApcEsdr 6:19 p. 31, 29 Tdf.; SibOr 3, 236; Aristides 9, 6; Justino, D. 14, 8; Taciano, Melitão, Atenágoras.) Referente à sujeição à morte (no mundo greco-romano, a diferença básica entre seres humanos e divindades reside na mortalidade daqueles e na imortalidade destas): mortal, oposto a <span class=\"greek\">ἀθάνατος</span> (Díon Crisóstomo 20 [37], 30; Plutarco, Mor. 960b; Herm. Wr. 1, 15; Fílon, Rer. Div. Her. 265; Josefo, Ant. 11, 56), D 4:8; Dg 6:8.</p><p class=\"entry-text\"><span class=\"greek\">σάρξ</span>, «carne» (Heráclito Estoico 74, 1 p. 98, 7 <span class=\"greek\">θνητὴ</span> <span class=\"greek\">σάρξ</span>, sobre a humanidade), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 4:11</a>. <span class=\"greek\">σῶμα</span>, «corpo» (Hipérides 6, 24; Pseudo-Platão, Axioch. 11, 370c; Fílon, Mut. Nom. 36; Josefo, Bell. 7, 344; Orígenes, C. Cels. 4, 15, 19; 4, 17, 15), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 6:12</a>; 8:11. <span class=\"greek\">θ</span>. <span class=\"greek\">ἐπίνοια</span>, Dg 7:1.</p><p class=\"entry-text\"><span class=\"greek\">ὁ</span> <span class=\"greek\">θ</span>., «o mortal», isto é, o simples ser humano (Empédocles: Vorsokrat. 31 B 112, 4 <span class=\"greek\">ὁ</span> <span class=\"greek\">θ</span>., «humano», em contraste com <span class=\"greek\">θεός</span>; Jó 30:23; Pv 3:13; 20:24; Fílon, Praem. 87), 1Cl 39:2; <span class=\"greek\">οἱ</span> <span class=\"greek\">θ</span>., «os mortais» (Homero e outros; Sb 4456, 4; 5829, 14; Sb 9:14), Dg 9:2 (em oposição a <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀθάνατος</span>). <span class=\"greek\">τὸ</span> <span class=\"greek\">θ</span>. (frequentemente em Fílon; Dídimo, Gen. 148, 27), 1Co 15:53s. (em oposição a <span class=\"greek\">ἀθανασία</span>, como Fílon, Aet. M. 46); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 5:4</a> (em oposição a <span class=\"greek\">ἡ</span> <span class=\"greek\">ζωή</span>). — DELG, s.v. <span class=\"greek\">θάνατος</span> II (cf. perfeito <span class=\"greek\">τέθνηκα</span>); M-M [Syll. 365, 10 refere-se a SIG2 = SIG 798, 10, acima]; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0169-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θορυβάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Presente passivo, 2ª pessoa do singular <span class=\"greek\">θορυβάζῃ</span> (ver os dois verbetes seguintes; Dositeu 71, 16; En 14:8; Etym. Mag. p. 633, 34; também Eusébio de Alexandria [MPG LXXXVI/1, 444c]). Na ativa, «causar perturbação»; na literatura considerada, apenas na passiva com sentido intransitivo: estar preocupado ou distraído <span class=\"greek\">περί</span> <span class=\"greek\">τι</span>, «por alguma coisa, com respeito a alguma coisa», acerca de uma dona de casa muito ocupada, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10:41</a> (variante de leitura <span class=\"greek\">τυρβάζῃ</span>, ver o respectivo verbete). — DELG, s.v. <span class=\"greek\">θόρυβος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0169-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θορυβέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Imperfeito <span class=\"greek\">ἐθορύβουν</span>; particípio aoristo <span class=\"greek\">θορυβήσαντος</span>, Sb 18:19. Passiva: imperfeito <span class=\"greek\">ἐθορυβούμην</span>; futuro, 3ª pessoa do plural <span class=\"greek\">θορυβυθήσονται</span>, Na 2:4; 1º aoristo <span class=\"greek\">ἐθορυβύθην</span>, Dn 8:17 LXX; particípio perfeito <span class=\"greek\">τεθορυβημένος</span>, Sir 40:6 (ver verbete precedente e seguinte; Sófocles, Heródoto e outros; inscrições, papiros, LXX; TestJos 7:5; Josefo; Justino, D. 9, 2 <span class=\"greek\">θορυβείτωσαν</span>).</p><p class=\"entry-text\">① Lançar na desordem, forma ativa com acusativo (cf. Sb 18:19; Josefo, Vi. 401; Ant. 18, 65): <span class=\"greek\">πόλιν</span>, «provocar tumulto na cidade, incitar uma revolta na cidade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.5\" target=\"_blank\" rel=\"noopener noreferrer\">At 17:5</a>.</p><p class=\"entry-text\">② Causar perturbação emocional, inquietar, agitar; na ativa em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:13</a>, Códice D (mas aqui <span class=\"greek\">θ</span>. talvez também seja empregado absolutamente). Predominantemente na passiva com sentido intransitivo: estar perturbado, angustiado, agitado (Cáriton 5, 8, 3; Apiano, Bell. Civ. 1, 25 §110; Polieno 8, 23, 19; Josefo, Ant. 17, 251), GPt 5:15. <span class=\"greek\">μὴ</span> <span class=\"greek\">θορυβεῖσθε</span>, «não vos perturbeis», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13:7</a>, Códice D; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.10\" target=\"_blank\" rel=\"noopener noreferrer\">At 20:10</a> (PTebt 411, 12 <span class=\"greek\">μηδὲν</span> <span class=\"greek\">μέντοι</span> <span class=\"greek\">θορυβηθῇς</span>). <span class=\"greek\">τί</span> <span class=\"greek\">θορυβεῖσθε</span>; «Por que vos agitais?», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5:39</a>. De um <span class=\"greek\">ὄχλος</span>: <span class=\"greek\">θορυβούμενος</span>, «agitado, em desordem», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:23</a> (Apiano, Bell. Civ. 5, 10 §42 <span class=\"greek\">ἡ</span> <span class=\"greek\">χώρα</span> <span class=\"greek\">θορυβουμένη</span>). — DELG, s.v. <span class=\"greek\">θόρυβος</span>; M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0169-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θόρυβος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver os dois verbetes anteriores; Píndaro, Heródoto e outros; OGI 48, 9; IMagnMai 114, 3; papiros, LXX, Fílon, Josefo; palavra tomada de empréstimo no hebraico rabínico).</p><p class=\"entry-text\">① Elevação de vozes que dificulta a compreensão: barulho, clamor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.34\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:34</a>; MPol 8:3; 9:1 (sobre a expressão <span class=\"greek\">μέγας</span> <span class=\"greek\">θ</span>., ver Hs 9, 3, 1 na acepção 3a, abaixo; Josefo, Ant. 17, 184); AcPl Ha 1, 28 (reconstituído).</p><p class=\"entry-text\">② Estado de confusão: desordem, agitação, 1Cl 57:4 (Pv 1:27).</p><p class=\"entry-text\">③ Estado ou condição de perturbação de intensidade variável: movimentação, excitação, tumulto (Xenofonte, An. 3, 4, 35; Apiano, Bell. Civ. 2, 118 §494).</p><p class=\"entry-text\">ⓐ Da movimentação desordenada de uma multidão: acerca dos pranteadores, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5:38</a> (embora os sentidos 1 e 2 também sejam possíveis); acerca de uma multidão de trabalhadores, Hs 9, 3, 1.</p><p class=\"entry-text\">ⓑ Do barulho e confusão de multidões excitadas (Fílon, In Flacc. 120; Josefo, Bell. 1, 201; 2, 611), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.1\" target=\"_blank\" rel=\"noopener noreferrer\">At 20:1</a>. <span class=\"greek\">γίνεται</span> <span class=\"greek\">θ</span>., «surge um tumulto» (cf. PTebt 15, 3 [114 a.C.] <span class=\"greek\">θορύβου</span> <span class=\"greek\">γενομένου</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">κώμῃ</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:5</a>; 27:24; GJs 21:1, seguido de <span class=\"greek\">ἕως</span> <span class=\"greek\">παύσηται</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θ</span>. em 25:1. <span class=\"greek\">μετὰ</span> <span class=\"greek\">θορύβου</span> (Polieno 6, 41, 1; Ez 7:11; Josefo, Ant. 5, 216), «com tumulto», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.18\" target=\"_blank\" rel=\"noopener noreferrer\">At 24:18</a>. — DELG; M-M; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0169-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θράσος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver verbete seguinte; Homero e outros; LXX, EpArist, Fílon; Josefo, Ant. 16, 66; Vi. 120.) Em sentido positivo, «coragem»; mas, quando a pessoa é indisciplinada, o impulso para uma ação ousada pode degenerar em «imprudência» ou «temeridade», e ela passa a dar a impressão de não considerar os sentimentos, preocupações ou pensamentos alheios; daí: arrogância, insolência, 1Cl 30:8. <span class=\"greek\">οὐ</span> <span class=\"greek\">δώσεις</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ψυχῇ</span> <span class=\"greek\">σου</span> <span class=\"greek\">θράσος</span>, «não concederás (= permitirás) arrogância à tua alma; não te tornarás arrogante», B 19:3; D 3:9 (cf. Diodoro Sículo 5, 29, 3 <span class=\"greek\">τὸ</span> <span class=\"greek\">θράσος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ψυχῆς</span>). — J. Wackernagel, Hellenistica, 1907, 15s.; DELG, s.v. <span class=\"greek\">θάρσος</span> B.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0169-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρασύτης, ητος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver verbete precedente; Tucídides e outros.) Ousadia, arrogância (Díon Crisóstomo 48 [65], 5; Sb 6026, 1 [séc. III d.C.]; Fílon, Spec. Leg. 3, 175 e outros), B 20:1; D 5:1. — DELG, s.v. <span class=\"greek\">θάρσος</span> B.</p></section></article>\n"};
